<?php
declare(strict_types=1);require_once __DIR__.'/config.php';
function curlOP($method,$url,$body=null,$token=null){$h=['Accept: application/json','Content-Type: application/json'];if($token)$h[]='Authorization: Bearer '.$token;$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>REQUEST_TIMEOUT,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_HTTPHEADER=>$h,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);if($method==='POST')curl_setopt($ch,CURLOPT_POST,true);if($body!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$raw=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($raw===false)throw new RuntimeException($err);$d=json_decode($raw,true);if(!is_array($d))$d=['message'=>'Răspuns invalid'];$d['_http_code']=$code;return $d;}
function saveT($d){file_put_contents(TOKEN_FILE,json_encode(['access_token'=>$d['access_token'],'refresh_token'=>$d['refresh_token'],'expires_at'=>time()+(int)($d['expires_in']??3600)-60],JSON_PRETTY_PRINT),LOCK_EX);@chmod(TOKEN_FILE,0600);}
function loginOP(){ $d=curlOP('POST',OFFICEPLUS_API.'/auth/token',['username'=>OFFICEPLUS_USERNAME,'password'=>OFFICEPLUS_PASSWORD]);if(empty($d['access_token']))throw new RuntimeException('Autentificarea API a eșuat.');saveT($d);return $d['access_token'];}
function tokenOP(){if(file_exists(TOKEN_FILE)){$d=json_decode(file_get_contents(TOKEN_FILE),true);if(is_array($d)&&!empty($d['access_token'])&&time()<(int)($d['expires_at']??0))return $d['access_token'];if(is_array($d)&&!empty($d['refresh_token']))try{$r=curlOP('POST',OFFICEPLUS_API.'/auth/refresh',['refresh_token'=>$d['refresh_token']]);if(!empty($r['access_token'])){saveT($r);return $r['access_token'];}}catch(Throwable $e){}}return loginOP();}
function officeplusRequest($method,$endpoint,$body=null,$retry=true){$r=curlOP($method,OFFICEPLUS_API.$endpoint,$body,tokenOP());if(($r['_http_code']??0)===401&&$retry){@unlink(TOKEN_FILE);return officeplusRequest($method,$endpoint,$body,false);}if(($r['_http_code']??0)>=400)throw new RuntimeException('HTTP '.$r['_http_code'].': '.($r['message']??$r['error']??'Eroare API'));unset($r['_http_code']);return $r;}
